function researchReportMetadata(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const metadata = (value as { metadata?: unknown }).metadata;
  return metadata && typeof metadata === 'object' && !Array.isArray(metadata)
    ? (metadata as Record<string, unknown>)
    : {};
}

function researchReportSessionId(value: unknown): string | null {
  const sessionId = researchReportMetadata(value).researchSessionId;
  return typeof sessionId === 'string' && sessionId ? sessionId : null;
}

function researchReportMessage(value: unknown): boolean {
  return researchReportMetadata(value).researchReport === true;
}

function withheldResearchReportMetadata(
  value: unknown,
  sessionId: string | null,
): Prisma.JsonObject {
  const metadata =
    value && typeof value === 'object' && !Array.isArray(value)
      ? (value as Record<string, Prisma.JsonValue>)
      : {};
  const trustSteps = Array.isArray(metadata.trustSteps)
    ? metadata.trustSteps.flatMap((value) => {
        const step =
          value && typeof value === 'object' && !Array.isArray(value)
            ? (value as Record<string, Prisma.JsonValue>)
            : {};
        const tool = publicResearchSourceTool(step.tool);
        const safe = {
          ...(tool ? { tool } : {}),
          ...(typeof step.count === 'number' && Number.isSafeInteger(step.count) && step.count >= 0
            ? { count: step.count }
            : {}),
          ...(['low', 'high'].includes(String(step.confidence))
            ? { confidence: step.confidence }
            : {}),
          ...(['done', 'error'].includes(String(step.status)) ? { status: step.status } : {}),
        } as Prisma.JsonObject;
        return Object.keys(safe).length ? [safe] : [];
      })
    : undefined;
  return {
    ...(sessionId ? { researchSessionId: sessionId } : {}),
    ...(metadata.researchReport === true ? { researchReport: true } : {}),
    ...(trustSteps ? { trustSteps } : {}),
    ...(metadata.intent === 'deep_research' ? { intent: metadata.intent } : {}),
    ...(['fast', 'deep'].includes(String(metadata.tier)) ? { tier: metadata.tier } : {}),
    ...(['fast', 'standard', 'deep', 'max'].includes(String(metadata.reasoningMode))
      ? { reasoningMode: metadata.reasoningMode }
      : {}),
    ...(typeof metadata.partial === 'boolean' ? { partial: metadata.partial } : {}),
    ...(typeof metadata.sourceCount === 'number' ? { sourceCount: metadata.sourceCount } : {}),
    reportBodyAccess: {
      status: 'withheld',
      reason: 'current_source_authorization_unavailable',
      recovery: 'research_session',
      ...(sessionId ? { researchSessionId: sessionId } : {}),
    },
  };
}

/**
 * Derive a count + human detail string from a tool result so the trust panel
 * can show what was actually found (citations), not just that a tool ran.
 * Handles the common Meri tool result shapes: { total, data: [...] },
 * { results: [...] }, { data: "<text>" }, { artifact }.
 */
function summarizeToolResultForTrust(payload: unknown): { count: number | null; detail: string } {
  if (!payload || typeof payload !== 'object') return { count: null, detail: '' };
  const rec = payload as Record<string, unknown>;
  if (typeof rec.error === 'string') return { count: null, detail: rec.error };

  const rows = Array.isArray(rec.data)
    ? (rec.data as unknown[])
    : Array.isArray(rec.results)
      ? (rec.results as unknown[])
      : null;
  const total = typeof rec.total === 'number' ? rec.total : rows ? rows.length : null;

  if (rows && rows.length) {
    const sample = rows
      .slice(0, 3)
      .map((r) => {
        if (r && typeof r === 'object') {
          const o = r as Record<string, unknown>;
          const label =
            o.title ??
            o.name ??
            o.subject ??
            o.companyName ??
            o.registrantName ??
            o.identifier ??
            o.billNumber;
          if (typeof label === 'string')
            return label.length > 60 ? `${label.slice(0, 57)}…` : label;
        }
        return null;
      })
      .filter((x): x is string => Boolean(x));
    const head =
      total != null ? `${total} result${total === 1 ? '' : 's'}` : `${rows.length} result(s)`;
    return { count: total, detail: sample.length ? `${head}: ${sample.join('; ')}` : head };
  }

  if (typeof rec.data === 'string' && rec.data.trim()) {
    const text = rec.data.trim();
    return { count: null, detail: text.length > 100 ? `${text.slice(0, 97)}…` : text };
  }
  if (rec.artifact && typeof rec.artifact === 'object') {
    const a = rec.artifact as Record<string, unknown>;
    return {
      count: null,
      detail: typeof a.title === 'string' ? `Created: ${a.title}` : 'Created artifact',
    };
  }
  return { count: total, detail: total != null ? `${total} result(s)` : 'Completed' };
}

/**
 * Extract persisted artifacts from a Meri tool result so the streaming brain
 * can save them as clioArtifact rows (the artifact panel reads these).
 * Tools return { artifact: {...} } or { artifacts: [...] } with persisted!==false.
 */
function extractToolArtifacts(value: unknown): Array<{
  title: string;
  kind: string;
  contentType: string | null;
  bodyText: string | null;
  s3Key: string | null;
  metadata: Prisma.InputJsonValue;
}> {
  if (!value || typeof value !== 'object') return [];
  const record = value as Record<string, unknown>;
  const candidates: unknown[] = [];
  if (record.artifact) candidates.push(record.artifact);
  if (Array.isArray(record.artifacts)) candidates.push(...record.artifacts);
  const out: ReturnType<typeof extractToolArtifacts> = [];
  for (const candidate of candidates) {
    if (!candidate || typeof candidate !== 'object') continue;
    const a = candidate as Record<string, unknown>;
    if (a.persisted === false) continue;
    const bodyText =
      typeof a.bodyText === 'string'
        ? a.bodyText
        : typeof a.body === 'string'
          ? a.body
          : typeof a.content === 'string'
            ? a.content
            : null;
    const s3Key = typeof a.s3Key === 'string' ? a.s3Key : null;
    const metadata =
      a.metadata && typeof a.metadata === 'object' && !Array.isArray(a.metadata)
        ? (a.metadata as Prisma.InputJsonObject)
        : {};
    // Image artifacts (F4 analysis charts) carry their PNG in metadata
    // instead of bodyText/s3Key.
    const hasImage = typeof (metadata as Record<string, unknown>).imageBase64 === 'string';
    if (!bodyText && !s3Key && !hasImage) continue;
    out.push({
      title: typeof a.title === 'string' && a.title.trim() ? a.title.trim() : 'Meri artifact',
      kind: typeof a.kind === 'string' && a.kind.trim() ? a.kind.trim() : 'document',
      contentType: typeof a.contentType === 'string' ? a.contentType : 'text/markdown',
      bodyText,
      s3Key,
      metadata,
    });
  }
  return out;
}

/** Historical Case46 rows keep a signed internal transport in conversation
 * metadata. It is server-only and never part of a public conversation response. */
function publicConversationMetadata<T>(value: T): T {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  if (!Object.hasOwn(value, 'governedArtifactCapture')) return value;
  const { governedArtifactCapture: _internal, ...rest } = value as Record<string, unknown>;
  return rest as T;
}

